// Checkout conversion fix: ensure paidEvents increment on successful payment
const { db } = require('../constants/db');

module.exports = async function processCheckout(req, res) {
  try {
    const { userId, amount, currency } = req.body;
    // Simulate payment processing
    const paymentSuccess = true; // Replace with real payment gateway
    if (paymentSuccess) {
      // Increment paidEvents metric
      await db.collection('metrics').updateOne(
        { key: 'paidEvents' },
        { $inc: { value: 1 } },
        { upsert: true }
      );
      // Log revenue
      await db.collection('revenue').insertOne({
        userId,
        amount,
        currency,
        timestamp: new Date()
      });
      res.status(200).json({ success: true });
    } else {
      res.status(400).json({ success: false, error: 'Payment failed' });
    }
  } catch (err) {
    console.error('Checkout error:', err);
    res.status(500).json({ success: false, error: 'Internal error' });
  }
};
